'use client';

import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';
import { me, type AuthUser } from '@/lib/auth';

type RequestStatus = 'Pending' | 'Approved' | 'Rejected';

interface DashboardApiResponse {
  success: boolean;
  message: string;
  data: {
    pending_requests: number;
    approved_requests: number;
    confirmed_schedules: number;
    load_summary: {
      total_units: number;
      max_units: number;
      remaining_units: number;
      utilization_percent: number;
      courses: Array<{ course_code: string; course_title: string; units: number }>;
    };
  };
}

interface ScheduleApiResponse {
  success: boolean;
  data: Array<{
    id: number;
    day_of_week: string;
    time_start: string;
    time_end: string;
    section?: { expected_students?: number };
    room?: { room_number?: string; building?: string; capacity?: number };
    course?: { course_code?: string; course_title?: string };
  }>;
}

interface RequestsApiResponse {
  success: boolean;
  data: Array<{
    id: number;
    status: string;
    preferred_start_time?: string;
    preferred_end_time?: string;
    created_at?: string;
    section?: { expected_students?: number };
    course?: { course_code?: string; course_title?: string };
    room?: { room_number?: string };
  }>;
}

const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
const DAY_MAP: Record<string, string> = {
  Monday: 'Mon', Tuesday: 'Tue', Wednesday: 'Wed', Thursday: 'Thu', Friday: 'Fri',
};

const toStatus = (value: string): RequestStatus =>
  value === 'Approved' || value === 'Rejected' ? value : 'Pending';

const fmtTime = (value?: string) => (value ? value.slice(0, 5) : '--:--');

const fmtDate = (value?: string) =>
  value
    ? new Date(value).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '--';

function StatusBadge({ status }: { status: RequestStatus }) {
  const map = {
    Pending: { bg: '#fff8e6', color: '#92620a', dot: '#f0a500' },
    Approved: { bg: '#e8f5ee', color: '#1a7a3c', dot: '#22a050' },
    Rejected: { bg: '#fdecea', color: '#d93025', dot: '#d93025' },
  };
  const s = map[status];
  return (
    <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-[11px] font-semibold" style={{ background: s.bg, color: s.color }}>
      <span className="w-1.5 h-1.5 rounded-full" style={{ background: s.dot }} />
      {status}
    </span>
  );
}

export default function InstructorDashboard() {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [dashboard, setDashboard] = useState<DashboardApiResponse['data'] | null>(null);
  const [schedule, setSchedule] = useState<ScheduleApiResponse['data']>([]);
  const [requests, setRequests] = useState<RequestsApiResponse['data']>([]);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const [meData, d, s, r] = await Promise.all([
          me(),
          api.get<DashboardApiResponse>('/instructor/dashboard'),
          api.get<ScheduleApiResponse>('/instructor/schedule'),
          api.get<RequestsApiResponse>('/requests?per_page=6'),
        ]);
        if (!mounted) return;
        setUser(meData);
        setDashboard(d.data);
        setSchedule(s.data ?? []);
        setRequests(r.data ?? []);
      } catch (e) {
        if (!mounted) return;
        setError(e instanceof Error ? e.message : 'Failed to load dashboard.');
      } finally {
        if (mounted) setLoading(false);
      }
    })();
    return () => {
      mounted = false;
    };
  }, []);

  const todayShort = useMemo(() => new Date().toLocaleDateString('en-US', { weekday: 'short' }), []);
  const classesToday = useMemo(
    () => schedule.filter((c) => DAY_MAP[c.day_of_week] === todayShort),
    [schedule, todayShort]
  );

  const dayMap = useMemo(() => {
    const map: Record<string, ScheduleApiResponse['data']> = { Mon: [], Tue: [], Wed: [], Thu: [], Fri: [] };
    schedule.forEach((c) => {
      const day = DAY_MAP[c.day_of_week];
      if (day && map[day]) map[day].push(c);
    });
    return map;
  }, [schedule]);

  return (
    <AppShell role="instructor" userName={user ? `${user.first_name} ${user.last_name}` : 'Instructor'} pageTitle="Dashboard">
      <div className="mb-6">
        <h1 className="text-[20px] font-bold" style={{ color: 'var(--color-text)' }}>
          Instructor Dashboard
        </h1>
        <p className="text-[13px] mt-0.5" style={{ color: 'var(--color-text-muted)' }}>
          {loading ? 'Loading...' : `You have ${classesToday.length} class${classesToday.length === 1 ? '' : 'es'} today.`}
        </p>
      </div>

      {error && (
        <div className="mb-5 p-3 rounded-lg border text-[12.5px]" style={{ borderColor: '#fecaca', background: '#fff1f2', color: '#9f1239' }}>
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="card card-body">
          <p className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>Classes Today</p>
          <p className="text-[24px] font-bold">{classesToday.length}</p>
        </div>
        <div className="card card-body">
          <p className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>Pending Requests</p>
          <p className="text-[24px] font-bold">{dashboard?.pending_requests ?? 0}</p>
        </div>
        <div className="card card-body">
          <p className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>Confirmed Schedules</p>
          <p className="text-[24px] font-bold">{dashboard?.confirmed_schedules ?? 0}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-5 mb-5">
        <div className="card card-body">
          <h2 className="text-[14px] font-semibold mb-2">Faculty Load</h2>
          <p className="text-[13px]" style={{ color: 'var(--color-text-secondary)' }}>
            {dashboard?.load_summary.total_units ?? 0} / {dashboard?.load_summary.max_units ?? 0} units
          </p>
          <p className="text-[12px]" style={{ color: 'var(--color-text-muted)' }}>
            Remaining: {dashboard?.load_summary.remaining_units ?? 0} ({dashboard?.load_summary.utilization_percent ?? 0}% used)
          </p>
          <div className="mt-3 flex flex-col gap-1.5">
            {(dashboard?.load_summary.courses ?? []).slice(0, 5).map((c) => (
              <div key={`${c.course_code}-${c.course_title}`} className="flex justify-between text-[12px]">
                <span className="truncate">{c.course_code} - {c.course_title}</span>
                <span>{c.units}u</span>
              </div>
            ))}
          </div>
          <Link href="/instructor/faculty-load" className="btn btn-outline btn-full text-[12px] mt-3">
            View Full Load Summary
          </Link>
        </div>

        <div className="lg:col-span-2 card card-body">
          <div className="flex items-center justify-between mb-3">
            <h2 className="text-[14px] font-semibold">This Week</h2>
            <Link href="/instructor/schedule" className="text-[12px]" style={{ color: 'var(--color-primary-light)' }}>
              Full schedule
            </Link>
          </div>
          <div className="grid grid-cols-5 gap-2">
            {DAYS.map((day) => (
              <div key={day}>
                <p className="text-[11px] font-semibold mb-1">{day}</p>
                <div className="flex flex-col gap-1">
                  {dayMap[day].length === 0 ? (
                    <div className="h-14 rounded-lg border border-dashed flex items-center justify-center text-[10px]" style={{ borderColor: 'var(--color-border)' }}>
                      Free
                    </div>
                  ) : (
                    dayMap[day].slice(0, 2).map((c) => (
                      <div key={c.id} className="rounded-lg p-2 text-[10.5px]" style={{ background: 'var(--color-primary-muted)' }}>
                        <p className="font-semibold">{c.course?.course_code ?? 'Course'}</p>
                        <p>{fmtTime(c.time_start)}</p>
                        <p>{c.room?.room_number ?? 'TBA'}</p>
                      </div>
                    ))
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="card">
        <div className="card-body pb-2 flex items-center justify-between">
          <h2 className="text-[14px] font-semibold">My Room Requests</h2>
          <Link href="/requests" className="text-[12px]" style={{ color: 'var(--color-primary-light)' }}>View all</Link>
        </div>
        <div className="overflow-x-auto">
          <table className="table-base">
            <thead>
              <tr>
                <th>Subject</th>
                <th>Room</th>
                <th>Date</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {requests.map((r) => (
                <tr key={r.id}>
                  <td className="text-[12px]">{r.course?.course_code ?? `Request #${r.id}`}</td>
                  <td className="text-[12px]">{r.room?.room_number ?? 'TBA'}</td>
                  <td className="text-[12px]">{fmtDate(r.created_at)}</td>
                  <td><StatusBadge status={toStatus(r.status)} /></td>
                </tr>
              ))}
              {!loading && requests.length === 0 && (
                <tr>
                  <td colSpan={4} className="text-center text-[12px]" style={{ color: 'var(--color-text-muted)' }}>
                    No requests found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </AppShell>
  );
}
